static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    // Extract year, month, day from YYYYMMDD format
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    // Validate month and day ranges (basic check)
    if (month < 1 || month > 12 || day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid date in timeBucket: " + timeBucket);
    }

    // Compute the start day of the bucket
    int bucketStartDay = 1 + ((day - 1) / dayStep) * dayStep;

    // Reconstruct the compressed time bucket
    return (long) year * 10000 + (long) month * 100 + bucketStartDay;
}

