private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null && suffix == null) {
        return true;
    }
    // If one is null and the other is not, no match
    if (str == null || suffix == null) {
        return false;
    }
    // Empty suffix is always a match for a non-null string
    if (suffix.isEmpty()) {
        return true;
    }
    // If suffix is longer than the string, it cannot match
    if (suffix.length() > str.length()) {
        return false;
    }
    try {
        if (ignoreCase) {
            // Compare in a case-insensitive manner
            String strLower = str.toLowerCase();
            String suffixLower = suffix.toLowerCase();
            return strLower.endsWith(suffixLower);
        } else {
            // Case-sensitive comparison
            return str.endsWith(suffix);
        }
    } catch (Exception e) {
        // In case of any unexpected runtime exception, return false
        return false;
