public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // If the path is absolute, ignore the leading '/'
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/", -1); // keep trailing empty segments
    for (String part : parts) {
        String value = part;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported
                throw new RuntimeException(e);
            } catch (IllegalArgumentException e) {
                // Malformed percent-encoding
                throw new IllegalArgumentException("Invalid percent-encoding in path segment: " + part, e);
            }
        }
        segments.add(new PathSegmentImpl(value, null));
    }
    return segments;
}

