public InputStream next() throws IOException {
    // Ensure the iterator is available
    if (fileIterator == null) {
        throw new IllegalStateException("File iterator not initialized");
    }

    // No more files
    if (!fileIterator.hasNext()) {
        return null;
    }

    java.io.File nextFile = fileIterator.next();

    // Defensive check for null
    if (nextFile == null) {
        return null;
    }

    // Validate the file
    if (!nextFile.exists()) {
        throw new IOException("File does not exist: " + nextFile);
    }
    if (!nextFile.isFile()) {
        throw new IOException("Not a regular file: " + nextFile);
    }
    if (!nextFile.canRead()) {
        throw new IOException("Cannot read file: " + nextFile);
    }

    // Return an InputStream for the file
    try {
        return new java.io.FileInputStream(nextFile);
    } catch (java.io.FileNotFoundException e) {
        throw new IOException("File not found: " + nextFile, e);
    }
}

