public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }
    // If the second character is uppercase, Introspector.decapitalize would not change the first character.
    // In that case, we leave the string unchanged to reverse the operation.
    if (name.length() > 1 && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    // Otherwise, capitalize the first character.
    char first = name.charAt(0);
    char upperFirst = Character.toUpperCase(first);
    if (first == upperFirst) {
        return name;
    }
    return upperFirst + name.substring(1);
}

