public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        // Timestamp formatting
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        String timestamp = sdf.format(new java.util.Date(event.getTimeStamp()));

        // Level
        String level = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";

        // Thread name
        String thread = event.getThreadName() != null ? event.getThreadName() : "UNKNOWN";

        // Logger name
        String logger = event.getLoggerName() != null ? event.getLoggerName() : "UNKNOWN";

        // Message
        String message = event.getMessage() != null ? event.getMessage().toString() : "";

        // Build base log line
        StringBuilder sb = new StringBuilder();
        sb.append(timestamp)
          .append(" [")
          .append(level)
          .append("] [")
          .append(thread)
          .append("] ")
          .append(logger)
          .append(" - ")
          .append(message);

        // Throwable information, if any
        if (event.getThrowableInformation() != null) {
            java.io.StringWriter sw = new java.io.StringWriter();
            java.io.PrintWriter pw = new java.io.PrintWriter(sw);
            event.getThrowableInformation().getThrowable().printStackTrace(pw);
            pw.flush();
            sb.append(System.lineSeparator()).append(sw.toString());
        }

        return sb.toString();
    } catch (Exception e) {
        // In case of any unexpected error, return a simple representation
        return "Error formatting LoggingEvent: " + e.getMessage();
    }
}

