@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Validate target type
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }

    // Handle null value
    if (value == null) {
        return null;
    }

    // Direct Character instance
    if (value instanceof Character) {
        return value;
    }

    // String conversion: must be a single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new Exception("Cannot convert String of length " + str.length() + " to Character");
        }
    }

    // Number conversion: cast to int and then to char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < 0 || intVal > 0xFFFF) {
            throw new Exception("Numeric value out of char range: " + intVal);
        }
        return (char) intVal;
    }

    // Unsupported types
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

