public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength){
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteLength == 0) {
        return this;
    }
    if (byteArrayValue == null) {
        // Put null bytes
        int newLen = length + byteLength;
        if (newLen > buffer.length) {
            int newCap = Math.max(buffer.length << 1, newLen);
            buffer = java.util.Arrays.copyOf(buffer, newCap);
        }
        java.util.Arrays.fill(buffer, length, newLen, (byte)0);
        length = newLen;
        return this;
    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset out of bounds");
    }
    if (byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("byteLength out of bounds");
    }
    int newLen = length + byteLength;
    if (newLen > buffer.length) {
        int newCap = Math.max(buffer.length << 1, newLen);
        buffer = java.util.Arrays.copyOf(buffer, newCap);
    }
    System.arraycopy(byteArrayValue, byteOffset, buffer, length, byteLength);
    length = newLen;
    return this;
}

