public int compare(Object aObj1, Object aObj2) {
    // Handle reference equality and nulls first
    if (aObj1 == aObj2) {
        return 0;
    }
    if (aObj1 == null) {
        return -1; // null is considered less than any non-null
    }
    if (aObj2 == null) {
        return 1; // any non-null is greater than null
    }

    try {
        // If both objects are Comparable and of the same runtime type, use natural ordering
        if (aObj1 instanceof Comparable && aObj2 instanceof Comparable
                && aObj1.getClass() == aObj2.getClass()) {
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) aObj1;
            return c1.compareTo(aObj2);
        }

        // Fallback: compare string representations
        return aObj1.toString().compareTo(aObj2.toString());
    } catch (ClassCastException e) {
        // Objects cannot be compared
        throw new IllegalArgumentException(
                "Objects are not comparable: " + aObj1 + ", " + aObj2, e);
    } catch (Exception e) {
        // Any other runtime issue
        throw new IllegalArgumentException(
                "Comparison failed for objects: " + aObj1 + ", " + aObj2, e);
    }
}

