private String parseToken(final char[] terminators) {
    // Validate the terminators array
    if (terminators == null || terminators.length == 0) {
        throw new IllegalArgumentException("terminators must not be null or empty");
    }

    // Ensure the source string is available
    if (input == null) {
        throw new IllegalStateException("Input string is not initialized");
    }

    StringBuilder token = new StringBuilder();

    // Read characters until a terminator is found or the end of the input is reached
    while (pos < input.length()) {
        char current = input.charAt(pos);

        // Check if the current character is one of the terminators
        boolean isTerminator = false;
        for (char t : terminators) {
            if (current == t) {
                isTerminator = true;
                break;
            }
        }

        if (isTerminator) {
            // Consume the terminator so that the next call starts after it
            pos++;
            break;
        }

        token.append(current);
        pos++;
    }

    return token.toString();
}

