private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    int[] suffixArr = new int[n];
    long suffixSum = 0;
    long totalSum = 0;
    for (int i = n - 1; i >= 0; i--){
        Integer val = bounds.get(i);
        long v = (val != null) ? val : 0;
        suffixSum += v;
        suffixArr[i] = (int) suffixSum; // cast to int; may overflow if sum exceeds Integer.MAX_VALUE
        totalSum += v;
    }
    List<Integer> suffixList = new ArrayList<>(n);
    for (int i = 0; i < n; i++){
        suffixList.add(suffixArr[i]);
    }
    return new Pair<>(suffixList, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    // Validate input
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null.");
    }
    int len = arr.length;
    if (from < 0 || to < 0 || from >= len || to >= len) {
        throw new IllegalArgumentException(
            "Indices out of bounds: from=" + from + ", to=" + to + ", array length=" + len);
    }
    if (from > to) {
        throw new IllegalArgumentException(
            "Invalid range: from (" + from + ") is greater than to (" + to + ").");
    }

    // Reverse the subarray in place
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    if (list == this) {
        // Nothing to do if the source is the same list
        return;
    }
    // If the source list is empty, nothing to move
    if (list.isEmpty()) {
        return;
    }

    // Iterate over the source list, removing each node and adding it to this list
    ListNodeImpl<E> current = list.getFirstNode();
    while (current != null) {
        // Save the next node before we modify the current one
        ListNodeImpl<E> next = current.getNext();
        try {
            // Remove from the source list
            list.removeListNode(current);
            // Add to this list
            this.addListNode(current);
        } catch (RuntimeException e) {
            // If any operation fails, wrap and rethrow to indicate a failure in moving nodes
            throw new IllegalStateException("Failed to move node during moveAllListNodes", e);
        }
        current = next;
    }
}

