private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return result;
    }
    // Ensure all keys are Integer
    for (K k : keys){
        if (!(k instanceof Integer)){
            throw new IllegalArgumentException("All keys must be of type Integer");
        }
    }
    // Create a sorted copy of the keys
    List<Integer> sorted = new ArrayList<>();
    for (K k : keys){
        sorted.add((Integer) k);
    }
    Collections.sort(sorted);
    // For each key, find the smallest key that is strictly greater
    for (K k : keys){
        int key = (Integer) k;
        int idx = Collections.binarySearch(sorted, key);
        int nextIdx;
        if (idx < 0){
            // key not found, insertion point
            nextIdx = -idx - 1;
        } else {
            // key found, skip duplicates to find strictly greater
            nextIdx = idx + 1;
            while (nextIdx < sorted.size() && sorted.get(nextIdx) == key){
                nextIdx++;
            }
        }
        if (nextIdx < sorted.size()){
            result.add(sorted.get(nextIdx));
        } else {
            // No greater key exists
            result.add(Integer.MAX_VALUE);
        }
    }
    return result;
}

