public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        throw new IllegalArgumentException("path cannot be null");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // If the relative path starts with a slash, treat it as an absolute path
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    boolean isAbsolute = path.startsWith("/");
    String[] pathParts = path.split("/");
    Deque<String> stack = new ArrayDeque<>();

    // Push the components of the base path onto the stack
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        stack.addLast(part);
    }

    // Process each component of the relative path
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            } else if (!isAbsolute) {
                // For a relative base path, keep leading ".." components
                stack.addLast("..");
            }
        } else {
            stack.addLast(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    // Handle the case where the result is empty
    if (result.length() == 0) {
        return isAbsolute ? "/" : "";
    }
    return result.toString();
}

