public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        if (timestamp <= 0 || expiredThreshold <= 0) {
            return false;
        }
        long currentTime = System.currentTimeMillis();
        return (currentTime - timestamp) > expiredThreshold;
    } catch (Exception e) {
        return false;
    }
}

Edge edgeToNext() {
    try {
        // Ensure the graph and node references are available
        if (graph == null) {
            throw new IllegalStateException("Graph reference is null");
        }
        if (previousNode == null || nextNode == null) {
            throw new IllegalStateException("Previous or next node is null");
        }

        // Resolve real nodes if either is virtual
        Node prev = previousNode.isVirtual() ? previousNode.getRealNode() : previousNode;
        Node next = nextNode.isVirtual() ? nextNode.getRealNode() : nextNode;

        // Retrieve the edge between the two real nodes
        Edge e = graph.getEdge(prev, next);
        if (e == null) {
            // Edge may not exist; return null or throw an exception as needed
            return null;
        }
        return e;
    } catch (Exception ex) {
        throw new IllegalStateException("Unable to retrieve edge to next node", ex);
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Handle null inputs gracefully
    if (str == null || substring == null) {
        return false;
    }

    int strLen = str.length();
    int subLen = substring.length();

    // Index must be within the bounds of the original string
    if (index < 0 || index > strLen) {
        return false;
    }

    // If the substring is longer than the remaining part of the original string, it cannot match
    if (index + subLen > strLen) {
        return false;
    }

    // Compare characters one by one
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getRenderedMessage();
    if (message == null) {
        message = "";
    }
    if (clients == null) {
        return;
    }
    for (Client client : clients) {
        if (client == null) {
            continue;
        }
        try {
            client.send(message);
        } catch (Exception e) {
            System.err.println("Failed to send log message to client: " + e);
        }
    }
}

private void checkIfPackedField() throws IOException {
    // Packed repeated fields are encoded with wire type 2 (length-delimited).
    // The current tag is assumed to be stored in the field `tag`.
    // Update internal state to indicate whether we are reading a packed field.
    int wireType = tag & 0x7;          // lower 3 bits of the tag
    int fieldNumber = tag >>> 3;       // remaining bits are the field number
    if (wireType == 2) {
        // Mark that we are currently reading a packed field
        isPacked = true;
        packedFieldNumber = fieldNumber;
    } else {
        isPacked = false;
    }
}

public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    for (int i = 0; i < 5; i++) {
        int b = read();
        if (b == -1) {
            if (i == 0) {
                return 0; // EOF before any bytes read
            } else {
                throw new IOException("EOF while reading tag");
            }
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Malformed varint");
}

final ByteVector put11(final int byteValue1,final int byteValue2){
    // Ensure the internal buffer exists and has enough space for two more bytes
    if (buf == null) {
        buf = new byte[2];
    } else if (pos + 2 > buf.length) {
        int newCap = Math.max(buf.length * 2, pos + 2);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, pos);
        buf = newBuf;
    }
    // Store the bytes, casting to byte to keep only the lower 8 bits
    buf[pos++] = (byte) byteValue1;
    buf[pos++] = (byte) byteValue2;
    return this;
}

private String buildContentRange() {
    // Assume the class has fields: long start, long end, long total
    // Validate the range values
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Content range start and end must be non-negative");
    }
    if (start > end) {
        throw new IllegalArgumentException("Content range start cannot be greater than end");
    }
    // Build the header value
    StringBuilder sb = new StringBuilder();
    sb.append("bytes ");
    sb.append(start).append('-').append(end);
    sb.append('/');
    if (total > 0) {
        sb.append(total);
    } else {
        sb.append('*');
    }
    return sb.toString();
}
